"""Advanced Python and mathematical foundations: bounded original labs."""
from python_guide_core import t

t(6,'dataclass-values','Dataclasses describe values','A dataclass generates initialization and value equality from annotated fields. frozen=True rejects field rebinding; it does not recursively freeze mutable members.','A mutable dataclass permits an assignment the frozen contract rejects.','@dataclass(frozen=True)\nclass Point:\n    x: int\np = Point(data)\ntry:\n    p.x = 9\n    result = False\nexcept FrozenInstanceError:\n    result = True',[(2,True),(0,True)],'frozen=True','frozen=False','from dataclasses import dataclass,FrozenInstanceError')
t(6,'instance-state','Keep mutable instance state per instance','Assign mutable fields on self during initialization. A class attribute is shared by instances and is appropriate only when the data is intentionally shared.','A class-level list joins state from unrelated objects.','class Bag:\n    def __init__(self):\n        self.items = []\na,b = Bag(),Bag()\na.items.append(data)\nresult = [a.items,b.items]',[(3,[[3],[]]),(0,[[0],[]])],'a,b = Bag(),Bag()','a = b = Bag()')
t(6,'property-validation','Validate updates through properties','A property can enforce an invariant on assignment while exposing ordinary attribute syntax. Store the backing value separately to avoid recursive setter calls.','Bypassing validation accepts a negative value outside the domain.','class Balance:\n    @property\n    def value(self):\n        return self._value\n    @value.setter\n    def value(self,x):\n        if x < 0:\n            raise ValueError("negative")\n        self._value = x\nb = Balance()\ntry:\n    b.value = data\n    result = b.value\nexcept ValueError:\n    result = None',[(4,4),(-1,None)],'if x < 0:','if False:')
t(6,'composition','Compose objects with explicit dependencies','Composition delegates one responsibility to an injected collaborator. Supplying the dependency explicitly makes behavior easy to replace in tests without inheritance.','Ignoring the collaborator breaks the configured behavior.','class Service:\n    def __init__(self,transform):\n        self.transform = transform\n    def run(self,x):\n        return self.transform(x)\nresult = Service(lambda x:x*3).run(data)',[(2,6),(0,0)],'return self.transform(x)','return x')
t(6,'value-equality','Define value equality intentionally','Dataclass equality compares the declared fields for matching dataclass types. Identity asks a separate question about whether references denote the same object.','Two separately created equal values do not have to share identity.','@dataclass\nclass Token:\n    value: int\na,b = Token(data),Token(data)\nresult = [a==b,a is b]',[(2,[True,False]),(0,[True,False])],'a==b','a is b','from dataclasses import dataclass')
t(6,'ordering-key','Order domain records explicitly','Order records using the business key rather than incidental field order. A tuple key makes primary and secondary ordering criteria explicit.','Reversing tuple-key components changes the primary criterion.','result = sorted(data,key=lambda x:(x[1],x[0]))',[([['b',1],['a',2],['c',1]],[['b',1],['c',1],['a',2]]),([],[])],'(x[1],x[0])','(x[0],x[1])')
t(6,'slots-layout','Slots restrict instance attributes','Declaring slots reserves a fixed set of instance attribute names when no dictionary is inherited. It can reduce per-instance overhead but does not freeze allowed fields.','Removing slots allows accidental new attribute names.','class Row:\n    __slots__ = ("x",)\nr = Row()\nr.x = data\ntry:\n    r.extra = 1\n    result = False\nexcept AttributeError:\n    result = True',[(3,True),(0,True)],'__slots__ = ("x",)','pass')
t(6,'descriptor-access','Descriptors participate in lookup','A descriptor implements attribute access through __get__. It receives the instance and owner, allowing reusable field policies independent of one class property.','Returning an unscaled stored value ignores the descriptor contract.','class Doubled:\n    def __get__(self,obj,owner):\n        return obj.raw*2\nclass Record:\n    value = Doubled()\nr = Record()\nr.raw = data\nresult = r.value',[(3,6),(-1,-2)],'obj.raw*2','obj.raw')
t(6,'iterator-protocol','Implement the iterator protocol','An iterator supplies __next__ and returns itself from __iter__. StopIteration signals exhaustion; a fresh iterable traversal needs a fresh iterator when replay is required.','Restarting position during iteration repeats earlier items.','class Once:\n    def __init__(self,items):\n        self.it = iter(items)\n    def __iter__(self):\n        return self\n    def __next__(self):\n        return next(self.it)\ng = Once(data)\nresult = [list(g),list(g)]',[([1,2],[[1,2],[]]),([], [[],[]])],'[list(g),list(g)]','[list(g),list(data)]')
t(6,'abstract-contract','Abstract classes prevent incomplete instances','An abstract base class can require a method before instantiation. An abstract method specifies a contract but does not automatically validate a concrete implementation.','Removing the abstract marker permits incomplete construction.','class Shape(ABC):\n    @abstractmethod\n    def area(self):\n        pass\ntry:\n    Shape()\n    result = False\nexcept TypeError:\n    result = True',[(1,True),(0,True)],'    @abstractmethod\n','', 'from abc import ABC,abstractmethod')
t(6,'context-exit','Context exit controls suppression','__exit__ receives exception details. Returning false propagates the exception after cleanup; returning true deliberately suppresses it.','Accidentally returning true hides a failure from the caller.','class Scope:\n    def __enter__(self):\n        return self\n    def __exit__(self,*error):\n        return False\ntry:\n    with Scope():\n        raise ValueError(str(data))\nexcept ValueError:\n    result = "propagated"\nelse:\n    result = "suppressed"',[(1,'propagated'),(0,'propagated')],'return False','return True')

t(7,'lazy-generator','Generators defer work','Calling a generator function creates an iterator without running its body. Each next resumes until a yield; unrequested elements are not computed yet.','Materializing the generator eagerly performs all work.','seen = []\ndef squares():\n    for x in data:\n        seen.append(x)\n        yield x*x\ng = squares()\nfirst = next(g,None)\nresult = [first,seen]',[([2,3],[4,[2]]),([], [None,[]])],'g = squares()','g = iter(list(squares()))')
t(7,'generator-send','Send values into a suspended generator','send resumes a generator and makes the supplied value the result of its suspended yield expression. Prime a new generator before sending a non-None value.','Calling next instead of send supplies None to the yield expression.','def receiver():\n    value = yield\n    yield value*2\ng = receiver()\nnext(g)\nresult = g.send(data)',[(3,6),(0,0)],'g.send(data)','next(g)')
t(7,'generator-close','Close suspended generators','A generator can hold resources across suspension. close raises GeneratorExit at the suspended yield so finally can release those resources before object collection.','Leaving a suspended generator open delays its finally cleanup.','events = []\ndef source():\n    try:\n        yield data\n    finally:\n        events.append("closed")\ng = source()\nnext(g)\ng.close()\nresult = list(events)',[(1,['closed']),(0,['closed'])],'g.close()','pass')
t(7,'yield-from','Delegate iteration with yield from','yield from delegates iteration to a subiterator. It yields the contained values rather than yielding the subiterator object as one value.','Yielding the list itself adds a nesting level.','def flattened():\n    for group in data:\n        yield from group\nresult = list(flattened())',[([[1,2],[3]],[1,2,3]),([],[])],'yield from group','yield group')
t(7,'decorator-wraps','Preserve decorator metadata','A decorator replaces a function with another callable. functools.wraps copies identifying metadata and records the wrapped function for introspection.','A bare wrapper hides the original name and signature metadata.','def decorate(fn):\n    @functools.wraps(fn)\n    def wrapper(x):\n        return fn(x)+1\n    return wrapper\n@decorate\ndef square(x):\n    return x*x\nresult = [square(data),square.__name__]',[(2,[5,'square']),(0,[1,'square'])],'    @functools.wraps(fn)\n','','import functools')
t(7,'cache-purity','Cache only compatible computations','lru_cache memoizes results for hashable argument combinations. It is suitable when reusing a prior result preserves semantics; impure computations need an invalidation policy.','A cache size of zero disables reuse.','calls = []\n@functools.lru_cache(maxsize=8)\ndef f(x):\n    calls.append(x)\n    return x*x\nf(data)\nf(data)\nresult = len(calls)',[(3,1),(0,1)],'maxsize=8','maxsize=0','import functools')
t(7,'pattern-match','Structural patterns extract data','match selects a structural pattern and binds names inside that pattern. A wildcard handles unsupported shapes without assuming every mapping has the same keys.','A literal key mismatch prevents the intended record pattern from matching.','match data:\n    case {"kind":"point","x":x}:\n        result = x\n    case _:\n        result = None',[({'kind':'point','x':4},4),({'kind':'line'},None)],'"point"','"line"')
t(7,'typing-runtime','Annotations do not enforce values','Type annotations document contracts and support static checking. Ordinary Python calls do not automatically reject a runtime value that violates an annotation.','Assuming annotations perform runtime validation produces false confidence.','def identity(x:int)->int:\n    return x\nresult = identity(data)',[('text','text'),(3,3)],'return x','return int(x)')
t(7,'protocol-shape','Protocols describe supported operations','A runtime-checkable Protocol can check the presence of required attributes. This shallow structural check does not validate full signatures, types or semantic behavior.','An object without the required operation does not satisfy the runtime shape check.','@runtime_checkable\nclass SizedThing(Protocol):\n    def __len__(self)->int: ...\nresult = isinstance(data,SizedThing)',[([1,2],True),(3,False)],'isinstance(data,SizedThing)','True','from typing import Protocol,runtime_checkable')
t(7,'metaclass-creation','Metaclasses govern class creation','A metaclass customizes how class objects are constructed. Use this mechanism sparingly when class-level behavior cannot be expressed with a simpler decorator or hook.','Changing the metaclass policy changes every class created through it.','class Meta(type):\n    def __new__(mcls,name,bases,ns):\n        ns["label"] = name.lower()\n        return super().__new__(mcls,name,bases,ns)\nclass Demo(metaclass=Meta):\n    pass\nresult = Demo.label',[(1,'demo'),(0,'demo')],'name.lower()','name.upper()')
t(7,'weak-ownership','Weak references do not own objects','weakref.ref observes an object without keeping it alive. When the last strong reference is removed, the weak reference becomes empty on this reference-counted interpreter.','Keeping a hidden strong alias prevents the observed object from being released.','class Item:\n    pass\nitem = Item()\nwatch = weakref.ref(item)\ndel item\nresult = watch() is None',[(1,True),(0,True)],'del item','alias = item\ndel item','import weakref')

t(8,'assert-contract','Assertions encode regression expectations','A regression compares actual behavior with a specified result. A test that only checks non-crashing execution cannot reject a wrong but well-formed answer.','Replacing the expected value with a tautology removes the behavioral check.','actual,expected = data\ntry:\n    assert actual == expected\n    result = True\nexcept AssertionError:\n    result = False',[([4,4],True),([4,5],False)],'actual == expected','actual == actual')
t(8,'unittest-case','Run actual unit assertions','unittest records assertion failures as test outcomes. Inspect wasSuccessful rather than assuming that construction of a TestCase means the test passed.','A test that compares a value with itself cannot reject a wrong expected value.','class Contract(unittest.TestCase):\n    def runTest(self):\n        self.assertEqual(data[0],data[1])\nreport = unittest.TestResult()\nContract().run(report)\nresult = report.wasSuccessful()',[([2,2],True),([2,3],False)],'data[0],data[1]','data[0],data[0]','import unittest')
t(8,'mock-boundary','Mock a dependency boundary','A mock can substitute a controlled result for an external dependency. Assert how it was called as well as what its caller returns; avoid mocking the behavior under test.','Passing the wrong argument still produces the configured mock result.','dependency = Mock(return_value=7)\nvalue = dependency(data)\nresult = [value,dependency.call_args.args[0]]',[(3,[7,3]),(0,[7,0])],'dependency(data)','dependency(99)','from unittest.mock import Mock')
t(8,'parameterized-boundaries','Test multiple boundary cases','A compact case table makes input/result relationships explicit. Include boundary and negative cases rather than testing only one convenient positive example.','all and any express different acceptance rules.','result = all(x >= 0 for x in data)',[([0,1],True),([-1,1],False),([],True)],'all(x >= 0','any(x >= 0')
t(8,'package-metadata','Read pyproject metadata','pyproject.toml stores build and project metadata in explicit tables. Use a TOML parser and read the intended table rather than relying on line positions.','Reading a different metadata key returns a different contract value.',"metadata = tomllib.loads(data)\nresult = metadata['project']['name']",[('[project]\nname="sample"\nversion="1.0"','sample'),('[project]\nname="other"\nversion="2.0"','other')],"['name']","['version']",'import tomllib')
t(8,'dependency-version','Record interpreter compatibility','An environment receipt must include the actual running interpreter. A major/minor compatibility check differs from claiming the newest release is installed.','A hard-coded incompatible major version misrepresents the environment.','result = sys.version_info.major == 3',[(1,True),(0,True)],'== 3','== 2','import sys')
t(8,'temp-isolation','Isolate tests with temporary directories','TemporaryDirectory creates a unique scope and removes it on exit. Assert the cleanup after leaving the context so teardown failures are observable.','Returning while still inside the resource scope does not establish cleanup.','with tempfile.TemporaryDirectory() as directory:\n    path = Path(directory)\n    (path/"value").write_text(str(data))\nresult = path.exists()',[(3,False),(0,False)],'result = path.exists()','result = True','import tempfile\nfrom pathlib import Path')
t(8,'logging-levels','Respect logging severity','Logging separates message severity from handler configuration. isEnabledFor predicts whether a logger accepts a given severity without writing sensitive data to a test log.','Lowering the logger threshold enables messages the contract suppresses.','logger = logging.Logger("lesson",level=logging.WARNING)\nresult = logger.isEnabledFor(data)',[(20,False),(40,True)],'level=logging.WARNING','level=logging.DEBUG','import logging')
t(8,'profile-call-count','Use profiler evidence','cProfile records actual calls made during a scoped workload. A call count establishes that workload only; timing and speed claims require representative measurements.','Skipping a workload call changes the observed count.','profiler = cProfile.Profile()\ndef work():\n    return 1\nprofiler.enable()\nfor _ in range(data):\n    work()\nprofiler.disable()\nresult = sum(row.callcount for row in profiler.getstats() if getattr(row.code,"co_name",None)=="work")',[(3,3),(0,0)],'range(data)','range(data+1)','import cProfile')
t(8,'bounded-history','Bound retained diagnostic history','Retain only the history needed by the feature. A bounded deque evicts the oldest records while keeping newest records in arrival order.','An unbounded list retains records beyond the stated limit.','history = deque(maxlen=2)\nfor x in data:\n    history.append(x)\nresult = list(history)',[([1,2,3],[2,3]),([],[])],'deque(maxlen=2)','deque()','from collections import deque')
t(8,'property-invariant','Check a transformation property','A property-based check describes a relationship across inputs. Reversing twice should recover the original sequence; generated inputs complement rather than replace domain examples.','A single reversal does not satisfy the round-trip property.','result = list(reversed(list(reversed(data)))) == data',[([1,2,3],True),([],True)],'list(reversed(list(reversed(data))))','list(reversed(data))')

t(9,'async-await','Await coroutine results','Calling an async function creates a coroutine. await runs it within an event-loop task and obtains the result after any suspension.','Returning the original input ignores the coroutine transformation.','async def double(x):\n    await asyncio.sleep(0)\n    return x*2\nresult = asyncio.run(double(data))',[(3,6),(0,0)],'return x*2','return x','import asyncio')
t(9,'gather-order','Gather preserves input ordering','gather schedules awaitables concurrently but returns results in the order the awaitables were supplied. Completion order is a separate scheduling detail.','Sorting returned values destroys the requested input order.','async def main():\n    async def value(x):\n        await asyncio.sleep(0)\n        return x\n    return await asyncio.gather(*(value(x) for x in data))\nresult = asyncio.run(main())',[([3,1,2],[3,1,2]),([],[])],'result = asyncio.run(main())','result = sorted(asyncio.run(main()))','import asyncio')
t(9,'taskgroup-scope','TaskGroup owns child tasks','A TaskGroup waits for its children before its context exits. Keep child handles when their results are needed and read results only after successful group completion.','Creating tasks without recording their handles loses the intended result inventory.','async def main():\n    async with asyncio.TaskGroup() as group:\n        tasks = [group.create_task(asyncio.sleep(0,result=x*2)) for x in data]\n    return [task.result() for task in tasks]\nresult = asyncio.run(main())',[([1,3],[2,6]),([],[])],'x*2','x','import asyncio')
t(9,'cancel-finally','Cancellation must run cleanup','Cancelling a suspended task raises CancelledError in that task. Await its completion and allow finally to release owned resources before considering teardown finished.','Returning without the finalizer event loses evidence of cleanup.','async def main():\n    events = []\n    async def work():\n        try:\n            await asyncio.Event().wait()\n        finally:\n            events.append("closed")\n    task = asyncio.create_task(work())\n    await asyncio.sleep(0)\n    task.cancel()\n    try:\n        await task\n    except asyncio.CancelledError:\n        pass\n    return events\nresult = asyncio.run(main())',[(1,['closed']),(0,['closed'])],'events.append("closed")','events.append("leaked")','import asyncio')
t(9,'async-timeout','Timeouts bound an await scope','asyncio.timeout cancels the current task when its deadline expires and translates that cancellation into TimeoutError outside the context. Cleanup still belongs in finally.','Suppressing a timeout and reporting success misstates completion.','async def main():\n    try:\n        async with asyncio.timeout(0):\n            await asyncio.Event().wait()\n    except TimeoutError:\n        return "timeout"\nresult = asyncio.run(main())',[(1,'timeout'),(0,'timeout')],'return "timeout"','return "success"','import asyncio')
t(9,'thread-pool','Join thread-pool work','A ThreadPoolExecutor context waits for owned work during shutdown. map returns results in input order; threads overlap waiting but do not guarantee CPU parallel speedups.','Ignoring the transformation changes every nonzero result.','with ThreadPoolExecutor(max_workers=2) as pool:\n    result = list(pool.map(lambda x:x*2,data))',[([1,3],[2,6]),([],[])],'lambda x:x*2','lambda x:x','from concurrent.futures import ThreadPoolExecutor')
t(9,'locked-update','Protect a compound state update','A lock defines a critical section around a shared read-modify-write operation. The invariant is the protected update, independent of incidental interpreter scheduling.','Assigning instead of accumulating loses contributions.','lock = threading.Lock()\nstate = [0]\ndef update(x):\n    with lock:\n        state[0] += x\nwith ThreadPoolExecutor(max_workers=2) as pool:\n    list(pool.map(update,data))\nresult = state[0]',[([1,2,3],6),([],0)],'state[0] += x','state[0] = x','import threading\nfrom concurrent.futures import ThreadPoolExecutor')
t(9,'bounded-queue','Queues express backpressure','A bounded queue rejects an immediate put when capacity is exhausted. Real producers can block or await capacity rather than allowing memory use to grow without a bound.','An unbounded queue accepts work beyond the intended capacity.','q = queue.Queue(maxsize=1)\nq.put_nowait(data)\ntry:\n    q.put_nowait(data)\n    result = False\nexcept queue.Full:\n    result = True',[(3,True),(0,True)],'maxsize=1','maxsize=0','import queue')
t(9,'child-process','Own subprocess completion','subprocess.run waits for its child, captures bounded lesson output, and reports the exit status. A timeout and scoped cleanup are required for less predictable workloads.','An explicit wrong exit code is a failure even with no stderr.','child = subprocess.run([sys.executable,"-c","import sys;sys.exit(int(sys.argv[1]))",str(data)],capture_output=True,text=True,timeout=5)\nresult = child.returncode',[(0,0),(2,2)],'str(data)','"0"','import subprocess,sys')
t(9,'future-errors','Retrieve worker failures','Calling result on a completed future re-raises the worker exception. A submitted task is not a successful operation until its result or failure has been observed.','Swallowing worker failure and reporting success changes the outcome.','def work():\n    raise ValueError(str(data))\nwith ThreadPoolExecutor(max_workers=1) as pool:\n    task = pool.submit(work)\n    try:\n        task.result()\n    except ValueError:\n        result = "failed"',[(1,'failed'),(0,'failed')],'result = "failed"','result = "succeeded"','from concurrent.futures import ThreadPoolExecutor')
t(9,'event-coordination','Events coordinate ownership','An Event signals a condition without sharing a mutable payload. Test its state explicitly; a signal and a completed computation are separate concepts.','Setting an event unconditionally reports a condition that has not occurred.','event = threading.Event()\nif data:\n    event.set()\nresult = event.is_set()',[(True,True),(False,False)],'if data:','if True:','import threading')

t(10,'vector-dot','Dot products combine aligned components','A dot product sums pairwise products of equal-length vectors. It measures alignment and underlies linear models; strict pairing rejects a malformed dimensional contract.','Adding components instead of multiplying changes the dot product.','result = sum(a*b for a,b in zip(*data,strict=True))',[([[1,2],[3,4]],11),([[0,0],[3,4]],0)],'a*b','a+b')
t(10,'l2-norm','Euclidean norms measure magnitude','The L2 norm is the square root of the sum of squared components. It is nonnegative and vanishes only for the zero vector.','The sum of components is not a Euclidean norm.','result = math.sqrt(sum(x*x for x in data))',[([3,4],5.0),([0,0],0.0)],'x*x','x','import math')
t(10,'sample-variance','Population and sample variance differ','The sample variance divides squared deviations by n-1 when estimating population variance from independent observations. The population formula uses n.','Using population variance underestimates this sample-variance contract.','result = statistics.variance(data)',[([1,2,3],1.0),([2,2],0.0)],'statistics.variance(data)','statistics.pvariance(data)','import statistics')
t(10,'conditional-bayes','Bayes updates a prior with evidence','Posterior probability is likelihood times prior divided by total evidence probability. Include false positives from the alternative class in the denominator.','Ignoring false positives makes the posterior unjustifiably large.','prior,sensitivity,false_positive = data\na = prior*sensitivity\nresult = a/(a+(1-prior)*false_positive)',[([0.5,0.8,0.2],0.8),([0.1,0.9,0.1],0.5)],'a+(1-prior)*false_positive','a')
t(10,'expectation','Expected values weight outcomes','An expectation sums each outcome times its probability. Probabilities must describe a normalized distribution; an unweighted average is a different quantity.','Ignoring probabilities gives the wrong expected outcome.','values,probabilities = data\nresult = sum(v*p for v,p in zip(values,probabilities,strict=True))',[([[0,10],[0.9,0.1]],1.0),([[2,4],[0.5,0.5]],3.0)],'v*p','v/len(values)')
t(10,'finite-gradient','Check a derivative numerically','A central difference estimates a derivative from symmetric perturbations. Choose a step that balances truncation and roundoff error; this is a check rather than a symbolic proof.','A one-sided difference with a large step has different error behavior.','h = 1e-4\nf = lambda x:x*x\nresult = (f(data+h)-f(data-h))/(2*h)',[(3,6.0),(-2,-4.0)],'f(data-h)','f(data)')
t(10,'gradient-descent','Move against the gradient','Gradient descent subtracts a positive learning rate times the gradient. On a quadratic with a suitable small step this moves toward its minimum.','Adding the gradient moves uphill on this quadratic.','x,rate = data\nresult = x-rate*2*x',[([3,0.1],2.4),([-2,0.25],-1.0)],'x-rate*2*x','x+rate*2*x')
t(10,'stable-softmax','Normalize exponentials stably','Subtract the largest logit before exponentiation. This preserves softmax probabilities while reducing overflow risk; the normalized probabilities sum to one.','Exponentiating very large raw logits can overflow.','m = max(data)\nweights = [math.exp(x-m) for x in data]\nresult = [x/sum(weights) for x in weights]',[([1000,1000],[0.5,0.5]),([0,0,0],[1/3,1/3,1/3])],'math.exp(x-m)','math.exp(x)','import math')
t(10,'cross-entropy','Cross entropy penalizes confident mistakes','For a one-hot target, cross entropy is the negative log probability assigned to the correct class. Probabilities must be positive; logits require a stable log-softmax implementation.','Negating a probability is not the negative logarithm loss.','result = -math.log(data)',[(1.0,0.0),(0.5,0.6931471805599453)],'-math.log(data)','-data','import math')
t(10,'entropy','Entropy measures distribution uncertainty','Discrete entropy sums -p log p and treats zero-probability terms as zero by continuity. A concentrated distribution has lower entropy than a uniform one.','Taking log zero is undefined without the zero-probability convention.','result = -sum(p*math.log(p) for p in data if p>0)',[([1,0],0.0),([0.5,0.5],0.6931471805599453)],'if p>0','if True','import math')
t(10,'confidence-standard-error','Sample size affects uncertainty','For independent observations with fixed sample standard deviation, the standard error of the mean scales as one over the square root of sample size.','Dividing by sample size instead of its square root shrinks uncertainty too fast.','std,n = data\nresult = std/math.sqrt(n)',[([4,16],1.0),([2,1],2.0)],'math.sqrt(n)','n','import math')
